/// `StreamBuilder` branch below treats it identically to `authenticated`.
/// The only extra reaction is scheduling the `ConfirmationDialog` overlay
/// on top of that same screen, from inside that same (sole) subscription —
/// `SessionRepository.statusStream`'s real implementation is a broadcast
/// `Stream.multi`, but several existing tests mock it as a plain
/// single-subscription `Stream.value(...)`, so a *second* independent
/// `.listen()` here would break those by listening to it twice.
class CerneApp extends StatefulWidget {
  const CerneApp({super.key});

  @override
  State<CerneApp> createState() => _CerneAppState();
}

class _CerneAppState extends State<CerneApp> {
  late final SessionRepository _sessionRepository;

  // Cached once: `SessionRepository.statusStream`'s getter builds a new
  // `Stream.multi` instance on every access (code review of
  // story-1-4-silent-session-refresh-persistence), so reading it straight
  // into `StreamBuilder.stream` on every `build()` would make it resubscribe
  // and lose its current status on each rebuild instead of staying on one
  // subscription for this widget's lifetime.
  late final Stream<SessionStatus> _statusStream;

  @override
  void initState() {
    super.initState();
    _sessionRepository = sl<SessionRepository>();
    _statusStream = _sessionRepository.statusStream;
    // Fire-and-forget: the outcome reaches the UI through `statusStream`
    // below, not through this call's return value. `restoreSession()`
    // already maps every internal failure to `Left`/an `unauthenticated`
    // emission and never throws. This `catchError` is NOT a UI recovery
    // path — its handler's return value is discarded by `unawaited` and
    // never reaches `statusStream`, so it does not unblock `build()`'s
    // `_BootLoadingScreen` branch. It exists purely so a future regression
    // that broke the "never throws" contract above would surface as a
    // logged message instead of an unhandled zone exception.
    unawaited(
      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
    );
  }

  /// Story 1.5's whole reaction to an `expired` snapshot (I/O matrix —
  /// every other status is a no-op, since `SessionRepositoryImpl` already
  /// only ever emits `expired` from `authenticated`, and this is called
  /// from the same `StreamBuilder` subscription that renders the screen,
  /// not a second one).
  ///
  /// `showGeneralDialog` (inside `ConfirmationDialog.show`) pushes a route,
  /// which must never happen mid-`build()` — deferred to
  /// `addPostFrameCallback`. Safe to call on every rebuild that still sees
  /// `expired` (not only the first): `ConfirmationDialog.show`'s own
  /// single-overlay guard makes every call after the first a no-op.
  void _maybeShowExpiryOverlay(BuildContext context, SessionStatus? status) {
    if (status != SessionStatus.expired) {
      return;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!context.mounted) {
        return;
      }
      ConfirmationDialog.show(
        context: context,
        builder: (dialogContext) => ConfirmationDialog(
          icon: Icons.lock_outline,
          title: 'Sessão expirada',
          message:
              'Sua sessão expirou por segurança. Entre novamente para '
              'continuar — sua conversa continua aqui.',
          caption: 'o histórico e a posição do scroll são preservados',
          confirmLabel: 'Entrar novamente',
          barrierColor: DesignTokens.colorScrim,
          onConfirm: () {
            Navigator.of(dialogContext).pop();
            Navigator.of(context).push(
              MaterialPageRoute(
                builder: (_) => const _BiometricReauthPlaceholder(),
              ),
            );
          },
        ),
      );
    });
  }

  // `catchError`'s handler must still complete the Future with a value of
  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
  // handler would try to complete it with `null`, which isn't assignable
  // to that non-nullable type and would itself throw.
  static Either<Failure, Unit> _asUnauthenticated(
    Object error,
    StackTrace stackTrace,
  ) {
    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
    return left(Failure.malformedResponse(message: error.toString()));
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: StreamBuilder<SessionStatus>(
        stream: _statusStream,
        builder: (context, snapshot) {
          if (!snapshot.hasData) {
            // No emission yet: brief-blank for the happy path (RNF01's
            // 300ms threshold) — `_BootLoadingScreen` only surfaces a
            // spinner once the wait actually crosses that.
            return const _BootLoadingScreen();
          }
          // Story 1.5: `expired` renders the exact same screen as
          // `authenticated` — the recovery overlay is layered on top
          // (scheduled below) instead of this branch ever returning a
          // different widget for it (Boundaries: "the authenticated
          // screen's widget instance is never replaced across
          // authenticated<->expired transitions").
          if (snapshot.data == SessionStatus.authenticated ||
              snapshot.data == SessionStatus.expired) {
            _maybeShowExpiryOverlay(context, snapshot.data);
            return const _PostAuthPlaceholder();
          }
          return AuthScreen(
            cubit: sl<AuthCubit>(),
            onAuthenticated: (context) => Navigator.of(context).pushReplacement(
              MaterialPageRoute(builder: (_) => const _PostAuthPlaceholder()),
            ),
          );
        },
      ),
    );
  }
}

